// To use your own custom logo as the default for all users,
// convert your image to a base64 string and paste it here.
// You can use an online tool like https://www.base64-image.de/
//
// Example: export const CUSTOM_LOGO_BASE64 = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgA....';

/**
 * A base64 encoded string for a custom default logo.
 * Set this to your logo's base64 string to override the default Chiliz icon.
 * If set to null, the original Chiliz icon will be used.
 */
export const CUSTOM_LOGO_BASE64: string | null = 'data:image/png;base64,';

